<?php
require __DIR__.'/includes/app.php';require_admin();header('Cache-Control: private, no-store');
$kind=field($_GET,'kind');$id=(int)field($_GET,'id');
function modal_action(string $action,int $id,string $label,string $class=''):void{?><form method="post" action="admin_action.php" data-admin-async><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><button class="btn <?= e($class) ?>"><?= e($label) ?></button></form><?php }
if($kind==='item'){
 $s=db()->prepare('SELECT i.*,u.name AS reporter_name FROM items i JOIN users u ON u.id=i.reporter_id WHERE i.id=?');$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);exit('Item not found.');}
 ?>
<div class="modal-item-image"><img src="<?= e(image_url($item['image_path'])) ?>" alt="<?= e($item['title']) ?>"></div><span class="admin-pill <?= e($item['status']==='claimed' ? 'claimed' : $item['moderation_status']) ?>"><?= e(ucfirst($item['moderation_status'])) ?> &middot; <?= e(ucfirst($item['status'])) ?></span><h3 class="modal-item-title"><?= e($item['title']) ?></h3><p class="modal-description"><?= e($item['description']) ?></p><dl class="modal-metadata"><dt>Category</dt><dd><?= e($item['category']) ?></dd><dt>Location</dt><dd><?= e($item['location']) ?></dd><dt>Lost / found date</dt><dd><?= e($item['date_reported']) ?></dd><dt>Reporter</dt><dd><?= e($item['reporter_name']) ?></dd><dt>Contact</dt><dd><?= e($item['contact_email']) ?><br><?= e($item['contact_phone']) ?></dd></dl><p class="modal-feedback" role="alert" hidden></p><div class="modal-actions"><?php if($item['moderation_status']==='pending'):modal_action('approve_report',$id,'Approve report');modal_action('reject_report',$id,'Reject','danger');endif ?><a class="btn secondary" href="public/edit.php?id=<?= $id ?>">Edit item</a><button class="btn secondary" type="button" data-modal-close>Close</button></div>
<?php
}elseif($kind==='claim'){
 $s=db()->prepare('SELECT r.*,i.title,i.status AS item_status,i.moderation_status FROM recovery_requests r JOIN items i ON i.id=r.item_id WHERE r.id=?');$s->execute([$id]);$claim=$s->fetch();if(!$claim){http_response_code(404);exit('Claim not found.');}
 ?>
<span class="admin-pill <?= e($claim['status']==='resolved' ? 'claimed' : $claim['status']) ?>"><?= $claim['status']==='resolved' ? 'Approved' : e(ucfirst($claim['status'])) ?></span><h3 class="modal-item-title"><?= e($claim['title']) ?></h3><dl class="modal-metadata"><dt>Claimant</dt><dd><?= e($claim['name']) ?></dd><dt>Email</dt><dd><?= e($claim['email']) ?></dd><dt>Submitted</dt><dd><?= e($claim['created_at']) ?></dd></dl><section class="evidence-box"><h4>Proof of ownership</h4><p class="modal-description"><?= e($claim['proof']) ?></p><?php $s=db()->prepare('SELECT id,original_name FROM recovery_attachments WHERE request_id=?');$s->execute([$id]);foreach($s->fetchAll() as $file): ?><a class="attachment-link" href="attachment.php?id=<?= (int)$file['id'] ?>">Download <?= e($file['original_name']) ?></a><?php endforeach ?></section><p class="modal-help">Verify the evidence against the actual item before approving a return.</p><p class="modal-feedback" role="alert" hidden></p><div class="modal-actions"><?php if($claim['status']==='pending'):if($claim['moderation_status']==='approved' && $claim['item_status']!=='claimed'):modal_action('approve_claim',$id,'Verify & approve');endif;modal_action('reject_claim',$id,'Reject claim','danger');endif ?><button class="btn secondary" data-review="item" data-id="<?= (int)$claim['item_id'] ?>">View item</button><button class="btn secondary" type="button" data-modal-close>Close</button></div>
<?php
}elseif($kind==='user'){
 $s=db()->prepare('SELECT a.id,a.email,a.student_id,a.role,a.active,u.name FROM accounts a JOIN users u ON u.id=a.user_id WHERE a.id=?');$s->execute([$id]);$user=$s->fetch();if(!$user){http_response_code(404);exit('Account not found.');}
 ?>
<form method="post" action="admin_action.php" class="modal-edit-form" data-admin-async><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="action" value="update_user"><div class="modal-form-grid"><label>Full name<input name="name" maxlength="100" value="<?= e($user['name']) ?>" required></label><label>Email<input type="email" name="email" maxlength="100" value="<?= e($user['email']) ?>" required></label><label>Student ID<input name="student_id" maxlength="40" value="<?= e($user['student_id']) ?>"></label><label>Role<select name="role"><option value="student" <?= $user['role']==='student' ? 'selected' : '' ?>>Student</option><option value="admin" <?= $user['role']==='admin' ? 'selected' : '' ?>>Administrator</option></select></label><label>Account access<select name="active"><option value="1" <?= $user['active'] ? 'selected' : '' ?>>Active</option><option value="0" <?= !$user['active'] ? 'selected' : '' ?>>Disabled</option></select></label></div><label>Your administrator password<input type="password" name="current_password" autocomplete="current-password" required></label><p class="modal-help">Changes end this user's existing sessions. Your own administrator access is protected.</p><p class="modal-feedback" role="alert" hidden></p><div class="modal-actions"><button class="btn">Save account</button><button class="btn secondary" type="button" data-modal-close>Cancel</button></div></form>
<?php
}else{http_response_code(400);echo 'Invalid review type.';}
